begin;
select no_plan();
insert into auth.users(id,email,is_anonymous) select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'article-'||n||'@test.local',false from generate_series(4001,4003)n;
insert into public.operations_members(user_id,role,expires_at) values('00000000-0000-4000-8000-000000004002','content',now()+interval '1 day'),('00000000-0000-4000-8000-000000004003','support',now()+interval '1 day');
create function pg_temp.login(n int) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','gina',jsonb_build_object('role','none','admin',false))::text,true)::void;$$;
set local role authenticated;
select pg_temp.login(4001);
select throws_ok($$select public.list_help_editor_articles()$$,'42501','forbidden','ordinary user cannot list drafts');
select throws_ok($$select public.get_help_editor_article('00000000-0000-4000-8000-000000004010')$$,'42501','forbidden','ordinary user cannot read unpublished versions');
select pg_temp.login(4003);
select throws_ok($$select public.list_help_editor_articles()$$,'42501','forbidden','support role cannot read editorial drafts');
select pg_temp.login(4002);
select lives_ok($$select public.save_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004010',0,'child-pin','tr','all','Çocuk PIN’i','Çocuk kendi profilini PIN ile açabilir.')$$,'create common article');
select public.review_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004010',1,'review','Instructions checked');
select public.review_help_article('00000000-0000-4000-8000-000000004020','00000000-0000-4000-8000-000000004010',1,'publish','Ready for parents');
select public.save_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004010',1,'child-pin','tr','all','Yeni PIN taslağı','<script>not executed</script> New draft only.');
select is(public.get_help_editor_article('00000000-0000-4000-8000-000000004010')->'published'->>'title','Çocuk PIN’i','published preview is exact old content');
select is(public.get_help_editor_article('00000000-0000-4000-8000-000000004010')->'draft'->>'title','Yeni PIN taslağı','draft has separate content');
select is(public.get_help_editor_article('00000000-0000-4000-8000-000000004010')->'draft'->'reviewed_at','null'::jsonb,'new draft not reviewed');
select is(public.get_help_articles('tr','all')->0->>'title','Çocuk PIN’i','public reader unaffected by new draft');
select lives_ok($$select public.review_help_article('00000000-0000-4000-8000-000000004020','00000000-0000-4000-8000-000000004010',1,'publish','Ready for parents')$$,'lost old publication receipt can replay after edit');
select is(public.get_help_editor_article('00000000-0000-4000-8000-000000004010')->>'revision','2','receipt replay never reverts new draft');
select throws_ok($$select public.review_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004010',1,'review','Stale editor')$$,'P0001','help_changed','stale review rejected');
select throws_ok($$select public.review_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004010',2,'publish','Unreviewed new draft')$$,'P0001','article_review_required','new draft needs own review');
select public.save_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004011',0,'ios-only','tr','ios','iPad kullanımı','iPad üzerinde uygulamayı açın.');
select public.save_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004012',0,'english','en','all','English help','This article is in English.');
select is(jsonb_array_length(public.list_help_editor_articles()),2,'null platform includes every platform in locale');
select is(jsonb_array_length(public.list_help_editor_articles(p_platform=>'all')),1,'literal all means generic platform only');
select is(public.list_help_editor_articles(p_platform=>'ios')->0->>'slug','ios-only','specific platform filter');
select is(jsonb_array_length(public.list_help_editor_articles(p_locale=>'en')),1,'locale isolation');
select throws_ok($$select public.list_help_editor_articles(p_platform=>'invented')$$,'P0001','invalid_input','reject unknown filter');
select throws_ok($$select public.list_help_editor_articles(p_after_slug=>'abc')$$,'P0001','invalid_input','partial cursor rejected');
select throws_ok($$select public.get_help_editor_article(gen_random_uuid())$$,'P0001','article_not_found','missing article explicit');
select throws_ok($$select * from public.help_article_versions$$,'42501',null,'no direct version table access');
select public.review_help_article(gen_random_uuid(),'00000000-0000-4000-8000-000000004010',2,'archive','Outdated information');
select is(public.get_help_editor_article('00000000-0000-4000-8000-000000004010')->'published','null'::jsonb,'archive removes published preview');
select is(public.get_help_editor_article('00000000-0000-4000-8000-000000004010')->'draft'->>'revision','2','archive retains draft');
reset role;
insert into public.help_articles(id,slug,locale,platform,revision) select ('00000000-0000-4000-8000-'||lpad((4100+n)::text,12,'0'))::uuid,'pagination-'||lpad(n::text,3,'0'),'tr','web',1 from generate_series(1,55)n;
insert into public.help_article_versions(article_id,revision,title,body,created_by) select id,1,'Page sample','A sufficiently long response.','00000000-0000-4000-8000-000000004002' from public.help_articles where slug like 'pagination-%';
set local role authenticated;
select is(jsonb_array_length(public.list_help_editor_articles(p_platform=>'web')),50,'bounded first page');
select is(jsonb_array_length(public.list_help_editor_articles(p_platform=>'web',p_after_slug=>'pagination-050',p_after_id=>'00000000-0000-4000-8000-000000004150')),5,'stable cursor returns remaining rows');
reset role;
update public.operations_members set revoked_at=now() where user_id='00000000-0000-4000-8000-000000004002';
set local role authenticated;
select throws_ok($$select public.get_help_editor_article('00000000-0000-4000-8000-000000004010')$$,'42501','forbidden','revoked content role denied immediately');
select * from finish();rollback;
